 15→
 16→@Injectable()
 17→export class SharesService {
 18→  constructor(
 19→    @InjectRepository(Share)
 20→    private readonly shareRepo: Repository<Share>,
 21→    @InjectRepository(ShareKey)
 22→    private readonly shareKeyRepo: Repository<ShareKey>,
 23→    @InjectRepository(User)
 24→    private readonly userRepo: Repository<User>
 25→  ) {}
 26→
 27→  /**
 28→   * Create a new share record with re-wrapped keys.
 29→   * Validates recipient exists and is not the sharer.
 30→   * Prevents duplicate active shares for the same item/recipient pair.
 31→   */
 32→  async createShare(sharerId: string, dto: CreateShareDto): Promise<Share> {
 33→    // Look up recipient by publicKey
 34→    // Strip 0x prefix if present — DB stores bare hex
 35→    const normalizedPubKey = dto.recipientPublicKey.startsWith('0x')
 36→      ? dto.recipientPublicKey.slice(2)
 37→      : dto.recipientPublicKey;
 38→    const recipient = await this.userRepo.findOne({
 39→      where: { publicKey: normalizedPubKey },
 40→    });
 41→
 42→    if (!recipient) {
 43→      throw new NotFoundException('Recipient not found');
 44→    }
 45→
 46→    if (recipient.id === sharerId) {
 47→      throw new ConflictException('Cannot share with yourself');
 48→    }
 49→
 50→    // Check for existing active share (same sharer, recipient, ipnsName)
 51→    const existing = await this.shareRepo.findOne({
 52→      where: {
 53→        sharerId,
 54→        recipientId: recipient.id,
 55→        ipnsName: dto.ipnsName,
 56→        revokedAt: IsNull(),
 57→      },
 58→    });
 59→
 60→    if (existing) {
 61→      throw new ConflictException('Share already exists for this item and recipient');
 62→    }
 63→
 64→    // Clean up any revoked-but-not-yet-rotated records for this triple
 65→    // so the new share can be created without unique constraint conflicts
 66→    const revoked = await this.shareRepo.find({
 67→      where: {
 68→        sharerId,
 69→        recipientId: recipient.id,
 70→        ipnsName: dto.ipnsName,
 71→        revokedAt: Not(IsNull()),
 72→      },
 73→    });
 74→    if (revoked.length > 0) {
 75→      await this.shareRepo.remove(revoked);
 76→    }
 77→
 78→    // Validate permission/IPNS-key invariant
 79→    const permission = dto.permission ?? 'read';
 80→    let encryptedIpnsKey: Buffer | null = null;
 81→
 82→    if (permission === 'write') {
 83→      if (!dto.encryptedIpnsKey) {
 84→        throw new BadRequestException('encryptedIpnsKey required for write permission');
 85→      }
 86→      encryptedIpnsKey = Buffer.from(dto.encryptedIpnsKey, 'hex');
 87→    } else if (dto.encryptedIpnsKey) {
 88→      throw new BadRequestException('encryptedIpnsKey must be omitted for read permission');
 89→    }
 90→
 91→    const share = this.shareRepo.create({
 92→      sharerId,
 93→      recipientId: recipient.id,
 94→      itemType: dto.itemType,
 95→      ipnsName: dto.ipnsName,
 96→      itemName: dto.itemName,
 97→      encryptedKey: Buffer.from(dto.encryptedKey, 'hex'),
 98→      permission,
 99→      encryptedIpnsKey,
100→      hiddenByRecipient: false,
101→      revokedAt: null,
102→    });
103→
104→    let savedShare: typeof share;
105→    try {
106→      savedShare = await this.shareRepo.save(share);
107→    } catch (err: unknown) {
108→      // Handle race condition: concurrent createShare for the same triple
109→      if (err instanceof Error && err.message?.includes('duplicate key')) {
110→        throw new ConflictException('Share already exists for this item and recipient');
111→      }
112→      throw err;
113→    }
114→
115→    // Create child keys if provided
116→    if (dto.childKeys && dto.childKeys.length > 0) {
117→      const shareKeys = dto.childKeys.map((ck) =>
118→        this.shareKeyRepo.create({
119→          shareId: savedShare.id,
120→          keyType: ck.keyType,
121→          itemId: ck.itemId,
122→          encryptedKey: Buffer.from(ck.encryptedKey, 'hex'),
123→        })
124→      );
125→      await this.shareKeyRepo.save(shareKeys);
126→    }
127→
128→    return savedShare;
129→  }
130→
131→  /**
132→   * Get active, non-hidden shares received by the user (paginated).
133→   * Includes sharer relation for publicKey display.
134→   */
135→  async getReceivedShares(
136→    recipientId: string,
137→    limit: number,
138→    offset: number
139→  ): Promise<{ shares: Share[]; total: number }> {
140→    const [shares, total] = await this.shareRepo.findAndCount({
141→      where: {
142→        recipientId,
143→        revokedAt: IsNull(),
144→        hiddenByRecipient: false,
145→      },
146→      relations: ['sharer'],
147→      order: { createdAt: 'DESC' },
148→      take: limit,
149→      skip: offset,
150→    });
151→    return { shares, total };
152→  }
153→
154→  /**
155→   * Get active shares sent by the user (paginated).
156→   * Includes recipient relation for publicKey display.
157→   */
158→  async getSentShares(
159→    sharerId: string,
160→    limit: number,
161→    offset: number
162→  ): Promise<{ shares: Share[]; total: number }> {
163→    const [shares, total] = await this.shareRepo.findAndCount({
164→      where: {
165→        sharerId,
166→        revokedAt: IsNull(),
167→      },
168→      relations: ['recipient'],
169→      order: { createdAt: 'DESC' },
170→      take: limit,
171→      skip: offset,
172→    });
173→    return { shares, total };
174→  }
