176→  /**
177→   * Get all re-wrapped child keys for a share.
178→   * Validates the requesting user is either sharer or recipient.
179→   */
180→  async getShareKeys(shareId: string, userId: string): Promise<ShareKey[]> {
181→    const share = await this.shareRepo.findOne({ where: { id: shareId } });
182→
183→    if (!share) {
184→      throw new NotFoundException('Share not found');
185→    }
186→
187→    if (share.sharerId !== userId && share.recipientId !== userId) {
188→      throw new ForbiddenException('Not authorized to access this share');
189→    }
190→
191→    return this.shareKeyRepo.find({
192→      where: { shareId },
193→      order: { createdAt: 'ASC' },
194→    });
195→  }
