371→  async updatePermission(
372→    shareId: string,
373→    sharerId: string,
374→    permission: 'read' | 'write',
375→    encryptedIpnsKey?: string
376→  ): Promise<void> {
377→    const share = await this.shareRepo.findOne({ where: { id: shareId } });
378→
379→    if (!share) {
380→      throw new NotFoundException('Share not found');
381→    }
382→
383→    if (share.sharerId !== sharerId) {
384→      throw new ForbiddenException('Only the sharer can change permission');
385→    }
386→
387→    if (share.revokedAt) {
388→      throw new ConflictException('Cannot change permission on a revoked share');
389→    }
390→
391→    if (permission === 'write') {
392→      if (!encryptedIpnsKey) {
393→        throw new BadRequestException('encryptedIpnsKey required for write permission');
394→      }
395→      share.permission = 'write';
396→      share.encryptedIpnsKey = Buffer.from(encryptedIpnsKey, 'hex');
397→      await this.shareRepo.save(share);
398→    } else {
399→      // Downgrade atomically: update share + delete file-ipns keys in one transaction
400→      await this.shareRepo.manager.transaction(async (txManager) => {
401→        share.permission = 'read';
402→        share.encryptedIpnsKey = null;
403→        await txManager.save(share);
404→        await txManager.delete(ShareKey, { shareId, keyType: 'file-ipns' });
