  1→import { useState, useEffect, useCallback, useRef } from 'react';
  2→import type { FilePointer } from '@cipherbox/core';
  3→import { Modal } from '../ui/Modal';
  4→import { useAuthStore } from '../../stores/auth.store';
  5→import { useFolder } from '../../hooks/useFolder';
  6→import { downloadFile, triggerBrowserDownload } from '../../services/download.service';
  7→import { resolveFileMetadata } from '../../services/file-metadata.service';
  8→import { fetchShareKeys } from '../../services/share.service';
  9→import { getSdkClient, hasSdkClient } from '../../lib/sdk-provider';
 10→import { encryptFile } from '../../services/file-crypto.service';
 11→import { addToIpfs } from '../../lib/api/ipfs';
 12→import '../../styles/text-editor-dialog.css';
 13→
 14→type TextEditorDialogProps = {
 15→  open: boolean;
 16→  onClose: () => void;
 17→  item: FilePointer | null;
 18→  parentFolderId: string;
 19→  /** Parent folder's decrypted AES-256 key (needed to decrypt file metadata) */
 20→  folderKey: Uint8Array | null;
 21→  /** When true, textarea is read-only and save is hidden */
 22→  readOnly?: boolean;
 23→  /** Share ID when viewing from a shared folder — uses re-wrapped file keys */
 24→  shareId?: string | null;
 25→  /** Save handler for shared files — updates file IPNS metadata via shared path */
 26→  onSaveSharedFile?: (item: FilePointer, newContent: Uint8Array) => Promise<void>;
 27→};
 28→
 29→/**
 30→ * Modal dialog for viewing/editing text files in-browser.
 31→ *
 32→ * In edit mode (default): full crypto round-trip with save.
 33→ * In read-only mode: decrypt and display only (used for shared files).
 34→ */
 35→export function TextEditorDialog({
 36→  open,
 37→  onClose,
 38→  item,
 39→  parentFolderId,
 40→  folderKey,
 41→  readOnly,
 42→  shareId,
 43→  onSaveSharedFile,
 44→}: TextEditorDialogProps) {
 45→  const [loading, setLoading] = useState(false);
 46→  const [saving, setSaving] = useState(false);
 47→  const [content, setContent] = useState('');
 48→  const [originalContent, setOriginalContent] = useState('');
 49→  const [error, setError] = useState<string | null>(null);
 50→  const textareaRef = useRef<HTMLTextAreaElement>(null);
 51→
 52→  const { updateFile } = useFolder();
 53→
 54→  const isDirty = content !== originalContent;
 55→  const lineCount = content.split('\n').length;
 56→
 57→  // Load file content when dialog opens
 58→  useEffect(() => {
 59→    if (!open || !item) {
 60→      setContent('');
 61→      setOriginalContent('');
 62→      setError(null);
 63→      setLoading(false);
 64→      setSaving(false);
 65→      return;
 66→    }
 67→
 68→    if (!folderKey) {
 69→      setLoading(false);
 70→      setError('Folder key not available');
 71→      return;
 72→    }
 73→
 74→    if (!item.fileMetaIpnsName) {
 75→      setLoading(false);
 76→      setError('File metadata IPNS name not available (legacy v1 file?)');
 77→      return;
 78→    }
 79→
 80→    let cancelled = false;
 81→    let focusRaf: number | undefined;
 82→    setLoading(true);
 83→    setError(null);
 84→
 85→    (async () => {
 86→      try {
 87→        const auth = useAuthStore.getState();
 88→        if (!auth.vaultKeypair) {
 89→          throw new Error('No keypair available - please log in again');
 90→        }
 91→
 92→        let plaintext: Uint8Array;
 93→
 94→        if (shareId) {
 95→          // Shared file path: use re-wrapped file key from share_keys,
 96→          // falling back to fileKeyEncrypted from metadata (for files uploaded by current user)
 97→          const [{ metadata: fileMeta }, keys] = await Promise.all([
 98→            resolveFileMetadata(item.fileMetaIpnsName, folderKey!),
 99→            fetchShareKeys(shareId),
100→          ]);
101→
102→          const fileKeyRecord = keys.find((k) => k.keyType === 'file' && k.itemId === item.id);
103→          if (!fileKeyRecord) {
104→            throw new Error('File key not available — the folder owner may need to re-share');
105→          }
106→          const wrappedKey = fileKeyRecord.encryptedKey;
107→
108→          plaintext = await downloadFile(
109→            {
110→              cid: fileMeta.cid,
111→              iv: fileMeta.fileIv,
112→              wrappedKey,
113→              originalName: item.name,
114→              encryptionMode: fileMeta.encryptionMode,
115→            },
116→            auth.vaultKeypair.privateKey
117→          );
118→        } else if (hasSdkClient()) {
119→          // Owner path via SDK: resolves IPNS, decrypts metadata, downloads + decrypts content
120→          const client = getSdkClient();
121→          plaintext = await client.downloadFromIpns(item.fileMetaIpnsName, folderKey!);
122→        } else {
123→          throw new Error('SDK not initialized — please log in again');
124→        }
125→
126→        if (cancelled) return;
127→
128→        const text = new TextDecoder().decode(plaintext);
129→        setContent(text);
130→        setOriginalContent(text);
131→        setLoading(false);
132→
133→        // Focus textarea after content loads (only in edit mode)
134→        if (!readOnly) {
135→          focusRaf = requestAnimationFrame(() => {
136→            textareaRef.current?.focus();
137→          });
138→        }
139→      } catch (err) {
140→        if (cancelled) return;
141→        setError(err instanceof Error ? err.message : 'Failed to load file');
142→        setLoading(false);
143→      }
144→    })();
145→
146→    return () => {
147→      cancelled = true;
148→      if (focusRaf !== undefined) cancelAnimationFrame(focusRaf);
149→    };
150→  }, [open, item, folderKey, shareId, readOnly]);
151→
152→  const handleSave = useCallback(async () => {
153→    if (!item || !isDirty) return;
154→
155→    setSaving(true);
156→    setError(null);
157→
158→    try {
159→      if (shareId && onSaveSharedFile) {
160→        // Shared file path: delegate to shared navigation handler
161→        const encoded = new TextEncoder().encode(content);
162→        await onSaveSharedFile(item, encoded);
163→      } else {
164→        // Owner path: encrypt and update folder metadata
165→        const auth = useAuthStore.getState();
166→        if (!auth.vaultKeypair) {
167→          throw new Error('No keypair available - please log in again');
168→        }
169→
170→        const encoded = new TextEncoder().encode(content);
171→        const file = new File([encoded], item.name);
172→        const encrypted = await encryptFile(file, auth.vaultKeypair.publicKey);
173→        const blob = new Blob([encrypted.ciphertext as BlobPart]);
174→        const { cid } = await addToIpfs(blob);
175→
176→        await updateFile(parentFolderId, {
177→          fileId: item.id,
178→          newCid: cid,
179→          newFileKeyEncrypted: encrypted.wrappedKey,
180→          newFileIv: encrypted.iv,
181→          newSize: encrypted.originalSize,
182→        });
183→      }
184→
185→      onClose();
186→    } catch (err) {
187→      setError(err instanceof Error ? err.message : 'Failed to save file');
188→      setSaving(false);
189→    }
190→  }, [item, content, isDirty, parentFolderId, updateFile, onClose, shareId, onSaveSharedFile]);
191→
192→  // Handle Ctrl/Cmd+S to save (edit mode only)
193→  useEffect(() => {
194→    if (!open || readOnly) return;
195→
196→    const handleKeyDown = (e: KeyboardEvent) => {
197→      if ((e.metaKey || e.ctrlKey) && e.key === 's') {
198→        e.preventDefault();
199→        if (isDirty && !saving && !loading) {
200→          handleSave();
201→        }
202→      }
203→    };
204→
205→    document.addEventListener('keydown', handleKeyDown);
206→    return () => document.removeEventListener('keydown', handleKeyDown);
207→  }, [open, readOnly, isDirty, saving, loading, handleSave]);
208→
209→  const handleDownload = useCallback(() => {
210→    if (!item || !content) return;
211→    const encoded = new TextEncoder().encode(content);
212→    triggerBrowserDownload(encoded, item.name, 'text/plain');
213→  }, [item, content]);
214→
215→  if (!item) return null;
216→
217→  const title = readOnly ? `View: ${item.name}` : `Edit: ${item.name}`;
218→  const isDisabled = saving || loading;
219→
220→  return (
221→    <Modal
222→      open={open}
223→      onClose={isDisabled ? undefined : onClose}
224→      title={title}
225→      className="text-editor-modal"
226→    >
227→      {loading ? (
228→        <div className="text-editor-loading">decrypting...</div>
229→      ) : (
230→        <div className="text-editor-body">
231→          <textarea
232→            ref={textareaRef}
233→            className="text-editor-textarea"
234→            value={content}
235→            onChange={readOnly ? undefined : (e) => setContent(e.target.value)}
236→            disabled={isDisabled}
237→            readOnly={readOnly}
238→            spellCheck={false}
239→            aria-label={`Content of ${item.name}`}
240→          />
241→          <div className={`text-editor-status${isDirty ? ' text-editor-status--modified' : ''}`}>
242→            <span>
243→              {'// '}
244→              {lineCount} {lineCount === 1 ? 'line' : 'lines'}
245→              {' | utf-8'}
246→              {readOnly ? ' | read-only' : ''}
247→              {isDirty ? ' | modified' : ''}
248→            </span>
249→          </div>
250→          {error && (
251→            <div className="text-editor-error">
252→              {'> '}
253→              {error}
254→            </div>
255→          )}
256→          <div className="text-editor-footer">
257→            {readOnly ? (
258→              <>
259→                <button
260→                  type="button"
261→                  className="dialog-button dialog-button--secondary"
262→                  onClick={handleDownload}
263→                >
264→                  --download
265→                </button>
266→                <button
267→                  type="button"
268→                  className="dialog-button dialog-button--primary"
269→                  onClick={onClose}
270→                >
271→                  close
272→                </button>
273→              </>
274→            ) : (
275→              <>
276→                <button
277→                  type="button"
278→                  className="dialog-button dialog-button--secondary"
279→                  onClick={onClose}
280→                  disabled={isDisabled}
281→                >
282→                  cancel
283→                </button>
284→                <button
285→                  type="button"
286→                  className="dialog-button dialog-button--primary"
287→                  onClick={handleSave}
288→                  disabled={isDisabled || !isDirty}
289→                >
290→                  {saving ? 'encrypting...' : '--save'}
291→                </button>
292→              </>
