209→// ---------------------------------------------------------------------------
210→// Post-upload / post-create share key propagation
211→// ---------------------------------------------------------------------------
212→
213→/**
214→ * Ensure sent shares cache is fresh (fetched within last 30s).
215→ * Returns the current sent shares array.
216→ */
217→async function ensureFreshSentShares(): Promise<SentShare[]> {
218→  const store = useShareStore.getState();
219→  if (store.lastSentFetchedAt && Date.now() - store.lastSentFetchedAt < 30_000) {
220→    return store.sentShares;
221→  }
222→  // Re-wrapping needs the full set — paginate through all pages
223→  const allShares = await fetchAllSentShares();
224→  useShareStore.getState().setSentShares(allShares);
225→  return allShares;
226→}
227→
228→/**
229→ * Fetch ALL sent shares by paginating through the API.
230→ * The API enforces a max limit of 100 per page.
231→ */
232→async function fetchAllSentShares(): Promise<SentShare[]> {
233→  const pageSize = 100;
234→  let offset = 0;
235→  const allShares: SentShare[] = [];
236→
237→  while (true) {
238→    const { shares, total } = await fetchSentShares(pageSize, offset);
239→    allShares.push(...shares);
240→    offset += shares.length;
241→    if (offset >= total || shares.length === 0) break;
242→  }
243→
244→  return allShares;
245→}
246→
247→/**
248→ * Check if a folder (by IPNS name) has any active shares.
249→ * Used to decide whether post-upload re-wrapping is needed.
250→ */
251→export async function hasActiveShares(folderIpnsName: string): Promise<boolean> {
252→  const shares = await ensureFreshSentShares();
253→  return shares.some((s) => s.ipnsName === folderIpnsName);
254→}
255→
256→/**
257→ * Find active shares that cover a given folder, including ancestor shares.
258→ * A folder is "covered" if it or any of its ancestor folders is shared.
259→ *
260→ * Walks the ancestor chain and checks each folder's IPNS name against sent shares.
261→ *
262→ * @param folderIpnsName - IPNS name of the current folder
263→ * @param folders - Current folder tree from the folder store
264→ * @param currentFolderId - ID of the current folder in the tree
265→ * @returns Array of sent shares covering this folder (may be from ancestor)
266→ */
267→export async function findCoveringShares(
268→  folderIpnsName: string,
269→  folders: Record<string, FolderNode>,
270→  currentFolderId: string | null
271→): Promise<SentShare[]> {
272→  const shares = await ensureFreshSentShares();
273→  if (shares.length === 0) return [];
274→
275→  // Collect all IPNS names from this folder up to root
276→  const ipnsNames = new Set<string>();
277→  ipnsNames.add(folderIpnsName);
278→
279→  let walkId = currentFolderId;
280→  while (walkId) {
281→    const node = folders[walkId];
282→    if (!node) break;
283→    ipnsNames.add(node.ipnsName);
284→    walkId = node.parentId;
285→  }
286→
287→  return shares.filter((s) => ipnsNames.has(s.ipnsName));
288→}
