290→/**
291→ * After adding a file or subfolder to a shared folder, re-wrap the new key
292→ * for all existing share recipients.
293→ *
294→ * This is a fire-and-forget operation -- failures are logged but don't block
295→ * the primary upload/create flow.
296→ *
297→ * IMPORTANT: Callers are responsible for zeroing `newItems[*].plaintextKey`
298→ * after this function completes. This function does NOT zero the keys because
299→ * some callers (e.g., subfolder creation) keep the key alive in the store.
300→ * Use a `finally` block to ensure zeroing even on errors.
301→ *
302→ * @param params.folderIpnsName - IPNS name of the folder being modified
303→ * @param params.folders - Current folder tree from the store
304→ * @param params.currentFolderId - ID of the current folder in the tree
305→ * @param params.newItems - New items whose keys need re-wrapping
306→ */
307→export async function reWrapForRecipients(params: {
308→  folderIpnsName: string;
309→  folders: Record<string, FolderNode>;
310→  currentFolderId: string | null;
311→  newItems: Array<{
312→    keyType: 'file' | 'folder';
313→    itemId: string;
314→    plaintextKey: Uint8Array;
315→  }>;
316→}): Promise<{ failedRecipients: string[] }> {
317→  const coveringShares = await findCoveringShares(
318→    params.folderIpnsName,
319→    params.folders,
320→    params.currentFolderId
321→  );
322→
323→  if (coveringShares.length === 0) return { failedRecipients: [] };
324→
325→  const failedRecipients: string[] = [];
326→
327→  // For each share recipient, re-wrap all new item keys
328→  for (const share of coveringShares) {
329→    try {
330→      const recipientPubKey = hexToBytes(
331→        share.recipientPublicKey.startsWith('0x')
332→          ? share.recipientPublicKey.slice(2)
333→          : share.recipientPublicKey
334→      );
335→
336→      const wrappedKeys: Array<{
337→        keyType: 'file' | 'folder';
338→        itemId: string;
339→        encryptedKey: string;
340→      }> = [];
341→
342→      for (const item of params.newItems) {
343→        const wrapped = await wrapKey(item.plaintextKey, recipientPubKey);
344→        wrappedKeys.push({
345→          keyType: item.keyType,
346→          itemId: item.itemId,
347→          encryptedKey: bytesToHex(wrapped),
348→        });
349→      }
350→
351→      // Add the wrapped keys to this share via API
352→      await addShareKeys(share.shareId, wrappedKeys);
353→    } catch (err) {
354→      console.warn(
355→        `[share] Failed to re-wrap keys for recipient ${share.recipientPublicKey.slice(0, 10)}...:`,
356→        err
357→      );
358→      failedRecipients.push(share.recipientPublicKey);
359→    }
360→  }
361→
362→  return { failedRecipients };
363→}
