368→
369→/** A revoked share pending key rotation. */
370→export type PendingRotation = {
371→  shareId: string;
372→  recipientPublicKey: string;
373→  itemType: 'folder' | 'file';
374→  ipnsName: string;
375→  itemName: string;
376→  revokedAt: string;
377→};
378→
379→/**
380→ * Fetch revoked shares that are pending key rotation from the server.
381→ * These are shares where revokedAt is set but the share has not been hard-deleted.
382→ */
383→export async function fetchPendingRotations(): Promise<PendingRotation[]> {
384→  const response = await sharesControllerGetPendingRotations();
385→
386→  return response.map((r) => ({
387→    shareId: r.shareId,
388→    recipientPublicKey: r.recipientPublicKey,
389→    itemType: r.itemType as 'folder' | 'file',
390→    ipnsName: r.ipnsName,
391→    itemName: r.itemName,
392→    revokedAt: String(r.revokedAt),
393→  }));
394→}
395→
396→/**
397→ * Check if a folder has pending rotations (revoked shares awaiting key rotation).
398→ * Called before any folder modification.
399→ *
400→ * @param folderIpnsName - IPNS name of the folder being modified
401→ * @returns true if there are revoked shares for this folder that need rotation
402→ */
403→export async function checkPendingRotation(folderIpnsName: string): Promise<boolean> {
404→  const pendingRotations = await fetchPendingRotations();
405→  return pendingRotations.some((r) => r.ipnsName === folderIpnsName);
406→}
407→
408→/**
409→ * Update the encrypted key on a share record after lazy key rotation.
410→ * Re-wraps the new folder key for a remaining (non-revoked) recipient.
411→ */
412→export async function updateShareKey(shareId: string, encryptedKey: string): Promise<void> {
413→  await sharesControllerUpdateShareEncryptedKey(shareId, { encryptedKey });
414→}
415→
416→/**
417→ * Hard-delete a revoked share after rotation is complete.
418→ */
419→export async function completeShareRotation(shareId: string): Promise<void> {
420→  await sharesControllerCompleteRotation(shareId);
421→}
422→
423→/**
424→ * Execute lazy key rotation for a folder.
425→ * Called when a folder modification is about to happen and pending rotations exist.
426→ *
427→ * Protocol:
428→ * 1. Generate new random folderKey
429→ * 2. Re-wrap new folderKey for each REMAINING (non-revoked) active recipient
430→ * 3. Update remaining shares with the new encrypted key
431→ * 4. Hard-delete revoked share records (rotation complete)
432→ * 5. Invalidate share cache
433→ *
434→ * NOTE: The actual folder metadata re-encryption (decrypt with old key, re-encrypt
435→ * with new key, re-publish IPNS) is handled by the caller (folder.service.ts)
436→ * since it has access to the folder's IPNS private key and publishing infrastructure.
437→ *
438→ * @returns The new folderKey for the caller to use
439→ */
440→export async function executeLazyRotation(params: {
441→  folderIpnsName: string;
442→  oldFolderKey: Uint8Array;
443→  ownerPublicKey: Uint8Array;
444→}): Promise<{ newFolderKey: Uint8Array }> {
445→  // 1. Generate new random 32-byte folderKey
446→  const newFolderKey = generateRandomBytes(32);
447→
448→  // 2. Fetch pending rotations and active shares for this folder
449→  const [pendingRotations, activeSentShares] = await Promise.all([
450→    fetchPendingRotations(),
451→    getSentSharesForItem(params.folderIpnsName),
452→  ]);
453→
454→  const revokedForFolder = pendingRotations.filter((r) => r.ipnsName === params.folderIpnsName);
455→  const revokedShareIds = new Set(revokedForFolder.map((r) => r.shareId));
456→
457→  // Active shares that are NOT revoked -- these recipients keep access
458→  const remainingShares = activeSentShares.filter((s) => !revokedShareIds.has(s.shareId));
459→
460→  // 3. Re-wrap new folderKey for each remaining recipient
461→  const reWrapFailures: string[] = [];
462→  for (const share of remainingShares) {
463→    try {
464→      const recipientPubKey = hexToBytes(
465→        share.recipientPublicKey.startsWith('0x')
466→          ? share.recipientPublicKey.slice(2)
467→          : share.recipientPublicKey
468→      );
469→      const wrapped = await wrapKey(newFolderKey, recipientPubKey);
470→      await updateShareKey(share.shareId, bytesToHex(wrapped));
471→    } catch (err) {
472→      console.warn(
473→        `[share] Failed to update share key for remaining recipient ${share.recipientPublicKey.slice(0, 10)}...:`,
474→        err
475→      );
476→      reWrapFailures.push(share.shareId);
477→    }
478→  }
479→
480→  if (reWrapFailures.length > 0) {
481→    newFolderKey.fill(0);
482→    throw new Error(
483→      `Key rotation failed: could not re-wrap key for ${reWrapFailures.length} recipient(s). ` +
484→        'Aborting to prevent inconsistent state.'
485→    );
486→  }
487→
488→  // 4. Hard-delete all revoked shares for this folder
489→  for (const revoked of revokedForFolder) {
490→    try {
491→      await completeShareRotation(revoked.shareId);
492→    } catch (err) {
493→      console.warn(`[share] Failed to complete rotation for share ${revoked.shareId}:`, err);
494→    }
495→  }
496→
497→  // 5. Invalidate the sent shares cache so next check fetches fresh state
498→  useShareStore.getState().setSentShares([]);
499→
500→  return { newFolderKey };
501→}
