137→/**
138→ * Hook for browsing shared content.
139→ *
140→ * Manages the "Shared with me" browsing experience.
141→ * Top-level view shows received shares as a flat list.
142→ * Clicking a shared folder navigates into it using re-wrapped keys.
143→ *
144→ * For write shares, also provides write operation handlers and 30s polling.
145→ */
146→export function useSharedNavigation(): UseSharedNavigationReturn {
147→  const [currentView, setCurrentView] = useState<SharedView>('list');
148→  const [currentShareId, setCurrentShareId] = useState<string | null>(null);
149→  const [sharedItems, setSharedItems] = useState<SharedListItem[]>([]);
150→  const [folderChildren, setFolderChildren] = useState<FolderChild[]>([]);
151→  const [folderKey, setFolderKey] = useState<Uint8Array | null>(null);
152→  const [breadcrumbs, setBreadcrumbs] = useState<SharedBreadcrumb[]>([]);
153→  const [isLoading, setIsLoading] = useState(true);
154→  const [error, setError] = useState<string | null>(null);
155→  const [permission, setPermission] = useState<'read' | 'write' | null>(null);
156→  const [ipnsName, setIpnsName] = useState<string | null>(null);
157→  const [currentSequenceNumber, setCurrentSequenceNumber] = useState<bigint | null>(null);
158→
159→  // Refs for values consumed in retry closures (C-01: avoids stale closure captures)
160→  const folderChildrenRef = useRef<FolderChild[]>([]);
161→  const sequenceNumberRef = useRef<bigint | null>(null);
162→
163→  // IPNS private key stored in ref to avoid re-renders; zeroed on cleanup
164→  const ipnsPrivateKeyRef = useRef<Uint8Array | null>(null);
165→
166→  // Navigation stack for folder browsing within a share
167→  const navStackRef = useRef<
168→    Array<{
169→      folderId: string;
170→      folderName: string;
171→      children: FolderChild[];
172→      folderKey: Uint8Array;
173→      ipnsName: string;
174→      sequenceNumber: bigint | null;
175→    }>
176→  >([]);
177→
178→  // Cache share keys per shareId with TTL to avoid refetching
179→  const shareKeysCache = useRef<
180→    Map<
181→      string,
182→      {
183→        keys: Array<{
184→          keyType: 'file' | 'folder' | 'file-ipns' | 'folder-ipns';
185→          itemId: string;
186→          encryptedKey: string;
187→        }>;
188→        fetchedAt: number;
189→      }
190→    >
191→  >(new Map());
192→
193→  // Polling interval ref for 30s sync
194→  const pollIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
195→
196→  /**
197→   * Zero the IPNS private key and clear the ref.
198→   */
199→  const zeroIpnsKey = useCallback(() => {
200→    if (ipnsPrivateKeyRef.current) {

200→    if (ipnsPrivateKeyRef.current) {
201→      ipnsPrivateKeyRef.current.fill(0);
202→      ipnsPrivateKeyRef.current = null;
203→    }
204→  }, []);
205→
206→  /**
207→   * Clear polling interval.
208→   */
209→  const clearPolling = useCallback(() => {
210→    if (pollIntervalRef.current) {
211→      clearInterval(pollIntervalRef.current);
212→      pollIntervalRef.current = null;
213→    }
214→  }, []);
215→
216→  /**
217→   * Handle silent revocation: transition from write to read-only.
218→   */
219→  const handleRevocation = useCallback(
220→    (showError?: boolean) => {
221→      zeroIpnsKey();
222→      setPermission('read');
223→      if (showError) {
224→        setError('> write access revoked -- folder is now read-only');
225→      }
226→    },
227→    [zeroIpnsKey]
228→  );
229→
230→  /**
231→   * Refresh folder contents from IPNS (used by polling and after write ops).
232→   * Returns the refreshed children, or null on failure.
233→   */
234→  const refreshFolderContents = useCallback(
235→    async (folderIpnsName: string, currentFolderKey: Uint8Array): Promise<FolderChild[] | null> => {
236→      try {
237→        const resolved = await resolveIpnsRecord(folderIpnsName);
238→        if (!resolved) return null;
239→
240→        const encryptedBytes = await fetchFromIpfs(resolved.cid);
241→        const encryptedJson = new TextDecoder().decode(encryptedBytes);
242→        const encrypted: EncryptedFolderMetadata = JSON.parse(encryptedJson);
243→        const metadata = await decryptFolderMetadata(encrypted, currentFolderKey);
244→
245→        const children = metadata.children ?? [];
246→        const seqNum = BigInt(resolved.sequenceNumber);
247→        setFolderChildren(children);
248→        folderChildrenRef.current = children;
249→        setCurrentSequenceNumber(seqNum);
250→        sequenceNumberRef.current = seqNum;
251→        return children;
252→      } catch {
253→        return null;
254→      }
255→    },
256→    []
257→  );
258→
259→  /**
260→   * Load received shares on mount.
261→   */
262→  useEffect(() => {
263→    let cancelled = false;
264→
265→    async function loadShares() {
266→      setIsLoading(true);
267→      setError(null);
268→
269→      try {
270→        // Paginate through all received shares (API max 100 per page)
271→        const pageSize = 100;
272→        let offset = 0;
273→        const shares: ReceivedShare[] = [];
274→
275→        while (true) {
276→          const page = await fetchReceivedShares(pageSize, offset);
277→          if (cancelled) return;
278→          shares.push(...page.shares);
279→          offset += page.shares.length;
280→          if (offset >= page.total || page.shares.length === 0) break;
281→        }
282→
283→        useShareStore.getState().setReceivedShares(shares);
284→
285→        const items: SharedListItem[] = shares.map((share) => ({
286→          share,
287→          children: null,
288→          folderKey: null,
289→        }));
290→
291→        setSharedItems(items);
292→      } catch (err) {
293→        if (cancelled) return;
294→        console.error('Failed to load shared items:', err);
295→        setError('Failed to load shared items');
296→      } finally {
297→        if (!cancelled) {
298→          setIsLoading(false);
299→        }
300→      }
301→    }
302→
303→    loadShares();
304→    return () => {
305→      cancelled = true;
306→      // Zero all decrypted folder keys on unmount
307→      setFolderKey((prev) => {
308→        if (prev) prev.fill(0);
309→        return null;
310→      });
311→      for (const entry of navStackRef.current) {
312→        entry.folderKey.fill(0);
313→      }
314→      navStackRef.current = [];
315→      zeroIpnsKey();
316→      clearPolling();
317→      shareKeysCache.current.clear();
318→    };
319→  }, [zeroIpnsKey, clearPolling]);
320→
321→  /** Cache TTL for share keys (60 seconds). */
322→  const SHARE_KEYS_CACHE_TTL = 60_000;
323→
324→  /**
325→   * Get share keys for a share, with TTL-based caching.
326→   */
327→  const getShareKeys = useCallback(async (shareId: string) => {
328→    const cached = shareKeysCache.current.get(shareId);
329→    if (cached && Date.now() - cached.fetchedAt < SHARE_KEYS_CACHE_TTL) {
330→      return cached.keys;
331→    }
332→
333→    const keys = await fetchShareKeys(shareId);
334→    shareKeysCache.current.set(shareId, { keys, fetchedAt: Date.now() });
335→    return keys;
336→  }, []);
337→
338→  /**
339→   * Navigate into a shared folder from the top-level list.
340→   */
341→  const navigateToShare = useCallback(
342→    async (shareId: string) => {
343→      const auth = useAuthStore.getState();
344→      if (!auth.vaultKeypair) {
345→        setError('No keypair available');
346→        return;
347→      }
348→
349→      const shareItem = sharedItems.find((s) => s.share.shareId === shareId);
350→      if (!shareItem) return;
351→
352→      const share = shareItem.share;
353→
354→      setIsLoading(true);
355→      setError(null);
356→      clearPolling();
357→
358→      try {
359→        // Unwrap the shared item's key with our private key
360→        const itemKey = await unwrapKey(
361→          hexToBytes(share.encryptedKey),
362→          auth.vaultKeypair.privateKey
363→        );
364→
365→        if (share.itemType === 'folder') {
366→          let folderKeyStored = false;
367→          try {
368→            // Resolve folder IPNS to get metadata
369→            const resolved = await resolveIpnsRecord(share.ipnsName);
370→            if (!resolved) {
371→              throw new Error('Could not resolve shared folder IPNS');
372→            }
373→
374→            // Fetch and decrypt folder metadata
375→            const encryptedBytes = await fetchFromIpfs(resolved.cid);
376→            const encryptedJson = new TextDecoder().decode(encryptedBytes);
377→            const encrypted: EncryptedFolderMetadata = JSON.parse(encryptedJson);
378→            const metadata = await decryptFolderMetadata(encrypted, itemKey);
379→
380→            // Unwrap IPNS private key for write shares
381→            if (share.permission === 'write' && share.encryptedIpnsKey) {
382→              try {
383→                const ipnsPrivKey = await unwrapKey(
384→                  hexToBytes(share.encryptedIpnsKey),
385→                  auth.vaultKeypair.privateKey
386→                );
387→                ipnsPrivateKeyRef.current = ipnsPrivKey;
388→              } catch (err) {
389→                console.error('Failed to unwrap IPNS key for write share:', err);
390→                // Fall back to read-only if IPNS key unwrap fails
391→              }
392→            }
393→
394→            // Set folder state (sync refs for retry closures — C-01)
395→            const children = metadata.children ?? [];
396→            const seqNum = BigInt(resolved.sequenceNumber);
397→            setCurrentView('folder');
398→            setCurrentShareId(shareId);
399→            setFolderChildren(children);

400→            folderChildrenRef.current = children;
401→            setFolderKey(itemKey);
402→            folderKeyStored = true;
403→            setBreadcrumbs([{ id: shareId, name: share.itemName }]);
404→            setPermission(ipnsPrivateKeyRef.current ? share.permission : 'read');
405→            setIpnsName(share.ipnsName);
406→            setCurrentSequenceNumber(seqNum);
407→            sequenceNumberRef.current = seqNum;
408→            navStackRef.current = [];
409→          } finally {
410→            if (!folderKeyStored) itemKey.fill(0);
411→          }
412→        } else {
413→          // For files, trigger download directly
414→          // itemKey is the parent folder key; downloadSharedFileFromShare unwraps its own copy
415→          itemKey.fill(0);
416→          await downloadSharedFileFromShare(share, auth.vaultKeypair.privateKey);
417→        }
418→      } catch (err) {
419→        console.error('Failed to navigate to shared item:', err);
420→        setError('Failed to open shared item');
421→      } finally {
422→        setIsLoading(false);
423→      }
424→    },
425→    [sharedItems, clearPolling]
426→  );
427→
428→  /**
429→   * Navigate into a subfolder within a shared folder.
430→   */
431→  const navigateToSubfolder = useCallback(
432→    async (folderId: string, folderName: string) => {
433→      const auth = useAuthStore.getState();
434→      if (!auth.vaultKeypair || !currentShareId) return;
435→
436→      setIsLoading(true);
437→      setError(null);
